--    bounced->pending (no DB 'bounced' status exists; the bounce and
--    suggested address are recorded in message), accepted/expired/
--    revoked as-is. token_hash = sha256 of a deterministic seed
--    string; openedAt has no column and lives only in the fixture.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 8. Audit entries — 12 from fixtures (the fixture file is a recent
--    page of a 126-entry log; totals live in the fixture only).
--    actorId 'system' maps to member 001 (audit_log.actor_id is a
--    NOT NULL FK); the full fixture entry is preserved in metadata.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 9. Assertions — the seed FAILS LOUDLY if the canon counts drift.
-- ---------------------------------------------------------------------------
do $$
declare
  v_org uuid := 'a3513721-6540-45a3-9f0a-07c3d8b74e32'::uuid;
begin
  if (select count(*) from public.memberships where org_id = v_org) <> 42 then
    raise exception 'seed assertion failed: memberships for Sevyn Labs must be 42';
  end if;
  if (select count(*) from public.roles where org_id = v_org) <> 9 then
    raise exception 'seed assertion failed: roles for Sevyn Labs must be 9';
  end if;
  if (select count(*) from public.permissions) <> 18 then
    raise exception 'seed assertion failed: permission catalog must be 18';
  end if;
  if (select count(*) from public.teams where org_id = v_org) <> 7 then
    raise exception 'seed assertion failed: teams for Sevyn Labs must be 7';
  end if;
  if (select count(*) from public.team_memberships tm
        join public.teams t on t.id = tm.team_id where t.org_id = v_org) <> 54 then
    raise exception 'seed assertion failed: team placements for Sevyn Labs must be 54';
  end if;
end $$;

commit;
